#!/bin/sh
# Regenerate the /hive/ page skeleton from om/hive-page/hive.om.
#
# hive.om is a seeded Omega program in program mode. The pinned compiler is a
# static AArch64 ELF built by the Omega seed, so this script runs on the build
# host (arm64) and the generated bytes are committed. GitHub Pages CI runs
# x86_64 and cannot execute the pin; it relies on the site-builder test, which
# re-reads main.html.sha256 instead.
#
#   OMEGA_OMC              compiler path (default: the pin named below)
#   OMEGA_ACCEPT_CHANGE=1  exit 0 even when main.html had to be rewritten
#
# Exit codes: 0 unchanged or written as asked, 2 compiler missing, 3 compiler
# sha256 mismatch, 4 main.html was stale (written, but the change needs a
# commit), 5 two runs of the generator disagreed, 6 the generator wrote nothing.
set -eu
cd "$(dirname "$0")"

omc=${OMEGA_OMC:-/home/drakestapleton/workspace/omega-mv-naming/seed/out/omc}
pin=$(tr -d ' \n' < omc.sha256)

if [ ! -f "$omc" ]; then
    printf 'hive.om: no compiler at %s\n' "$omc" >&2
    printf 'hive.om: set OMEGA_OMC to a seed/out/omc whose sha256 is %s\n' "$pin" >&2
    exit 2
fi

have=$(sha256sum "$omc" | cut -d' ' -f1)
if [ "$have" != "$pin" ]; then
    printf 'hive.om: compiler sha256 mismatch\n  recorded %s\n  found    %s\n' "$pin" "$have" >&2
    exit 3
fi

work=$(mktemp -d "${TMPDIR:-/tmp}/hive-page.XXXXXX")
trap 'rm -rf "$work"' EXIT HUP INT TERM

"$omc" < hive.om > "$work/hive"
chmod +x "$work/hive"
"$work/hive" > "$work/first.html"
"$work/hive" > "$work/second.html"

if ! cmp -s "$work/first.html" "$work/second.html"; then
    printf 'hive.om: two runs disagree; the generator is not deterministic\n' >&2
    exit 5
fi
if [ ! -s "$work/first.html" ]; then
    printf 'hive.om: the generator wrote nothing\n' >&2
    exit 6
fi

stale=0
if [ -f main.html ] && ! cmp -s main.html "$work/first.html"; then
    stale=1
fi
cp "$work/first.html" main.html
hash=$(sha256sum main.html | cut -d' ' -f1)
printf '%s  main.html\n' "$hash" > main.html.sha256

printf 'omc sha256 %s\n' "$have"
printf 'main.html %s bytes\n' "$(wc -c < main.html | tr -d ' ')"
printf 'main.html sha256 %s\n' "$hash"

if [ "$stale" = 1 ]; then
    printf 'hive.om: main.html was out of date and has been rewritten; commit it\n' >&2
    if [ "${OMEGA_ACCEPT_CHANGE:-0}" != "1" ]; then
        exit 4
    fi
fi
